-- Recognize only the complete reviewed shared ancestry successor. No content is written.
do $shared_upgrade$
declare body text;
begin
 if (exists(select 1 from pg_catalog.pg_proc p
  where p.oid=pg_catalog.to_regprocedure('public.treasure_vault_terminal_status_v1()')
    and pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to((p.prosrc)::text,'UTF8')),'hex')='fbdf75894b97980ba3382a2a74ee2dd8f28929a129b21ca423942e0aeba544b2'
    and p.prokind='f' and p.prolang=(select l.oid from pg_catalog.pg_language l where l.lanname='sql')
    and p.provolatile='s' and p.prosecdef is false and p.proisstrict is false and p.proleakproof is false
    and p.proparallel='u' and p.procost=100 and p.prorows=1
    and p.pronargs=0 and p.pronargdefaults=0 and p.proretset is true
    and p.prorettype=pg_catalog.to_regtype('record')
    and p.proallargtypes=array[pg_catalog.to_regtype('boolean')::oid,pg_catalog.to_regtype('boolean')::oid]
    and p.proargmodes=array['t','t']::"char"[] and p.proargnames=array['recognized','passed']::text[]
    and p.proconfig=array['search_path=""']::text[] and p.proowner=pg_catalog.to_regrole('postgres')
    and (select count(*)=3
      and count(*) filter(where a.grantee=pg_catalog.to_regrole('postgres'))=1
      and count(*) filter(where a.grantee=pg_catalog.to_regrole('service_role'))=1
      and count(*) filter(where a.grantee=pg_catalog.to_regrole('supabase_read_only_user'))=1
      and bool_and((a.privilege_type='EXECUTE' and a.is_grantable is false
      and a.grantor=pg_catalog.to_regrole('postgres')
      and a.grantee in(pg_catalog.to_regrole('postgres'),pg_catalog.to_regrole('service_role'),pg_catalog.to_regrole('supabase_read_only_user'))) is true)
      from pg_catalog.aclexplode(coalesce(p.proacl,pg_catalog.acldefault('f',p.proowner))) a)
    and pg_catalog.has_function_privilege('postgres',p.oid,'EXECUTE')
    and pg_catalog.has_function_privilege('service_role',p.oid,'EXECUTE')
    and pg_catalog.has_function_privilege('supabase_read_only_user',p.oid,'EXECUTE'))) is true then return; end if;
 if (exists(select 1 from pg_catalog.pg_proc p
  where p.oid=pg_catalog.to_regprocedure('public.treasure_vault_terminal_status_v1()')
    and pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to((p.prosrc)::text,'UTF8')),'hex')='daea9d6e1e03e4adbb63c5ab1e06ad540f09b032ae32a1a0b85e421f43d07ded'
    and p.prokind='f' and p.prolang=(select l.oid from pg_catalog.pg_language l where l.lanname='sql')
    and p.provolatile='s' and p.prosecdef is false and p.proisstrict is false and p.proleakproof is false
    and p.proparallel='u' and p.procost=100 and p.prorows=1
    and p.pronargs=0 and p.pronargdefaults=0 and p.proretset is true
    and p.prorettype=pg_catalog.to_regtype('record')
    and p.proallargtypes=array[pg_catalog.to_regtype('boolean')::oid,pg_catalog.to_regtype('boolean')::oid]
    and p.proargmodes=array['t','t']::"char"[] and p.proargnames=array['recognized','passed']::text[]
    and p.proconfig=array['search_path=""']::text[] and p.proowner=pg_catalog.to_regrole('postgres')
    and (select count(*)=3
      and count(*) filter(where a.grantee=pg_catalog.to_regrole('postgres'))=1
      and count(*) filter(where a.grantee=pg_catalog.to_regrole('service_role'))=1
      and count(*) filter(where a.grantee=pg_catalog.to_regrole('supabase_read_only_user'))=1
      and bool_and((a.privilege_type='EXECUTE' and a.is_grantable is false
      and a.grantor=pg_catalog.to_regrole('postgres')
      and a.grantee in(pg_catalog.to_regrole('postgres'),pg_catalog.to_regrole('service_role'),pg_catalog.to_regrole('supabase_read_only_user'))) is true)
      from pg_catalog.aclexplode(coalesce(p.proacl,pg_catalog.acldefault('f',p.proowner))) a)
    and pg_catalog.has_function_privilege('postgres',p.oid,'EXECUTE')
    and pg_catalog.has_function_privilege('service_role',p.oid,'EXECUTE')
    and pg_catalog.has_function_privilege('supabase_read_only_user',p.oid,'EXECUTE'))) is not true then raise exception 'Shared ancestry helper predecessor differs'; end if;
 select prosrc into strict body from pg_catalog.pg_proc where oid=pg_catalog.to_regprocedure('public.treasure_vault_terminal_status_v1()');
 body:=replace(body,$shared_before_0$global_terminal_actual as materialized($shared_before_0$,$shared_after_0$global_shared_settings as materialized(select $shared104${"patches":[{"table":"ancestry","id":3,"before":{"id":3,"name":"Elf","uuid":"6069556547543259","rarity":"COMMON","version":"1.0","trait_id":1348,"meta_data":{"source":{"url":"https://2e.aonprd.com/Ancestries.aspx?ID=60","book":"Player Core","page":"46"}},"created_at":"2023-12-02T22:15:58.556798+00:00","deprecated":null,"operations":[{"id":"2ab7d55b-60a2-4051-9307-e4c73a6d6596","data":{"value":6,"variable":"MAX_HEALTH_ANCESTRY"},"type":"setValue"},{"id":"09cbf36d-44d6-436d-9456-5499516314aa","data":{"value":"medium","variable":"SIZE"},"type":"setValue"},{"id":"72506287-ce22-4033-866d-ab849ac4ec9e","data":{"value":30,"variable":"SPEED"},"type":"setValue"},{"id":"ca332abb-d0ae-43d6-915b-bb85688cf91e","data":{"value":{"value":-1},"variable":"ATTRIBUTE_CON"},"type":"adjValue"},{"id":"2406087d-787e-4a0d-9807-e167794d3471","data":{"languageId":81},"type":"giveLanguage"},{"id":"d6dea13c-9849-4988-910b-786afad7f468","data":{"languageId":84},"type":"giveLanguage"},{"id":"e423312d-baab-4e75-91ec-11599102f395","data":{"value":"[\n  \"Draconic\",\n  \"Empyrean\",\n  \"Fey\",\n  \"Gnomish\",\n  \"Goblin\",\n  \"Kholo\",\n  \"Orcish\"\n]","variable":"CORE_LANGUAGES"},"type":"setValue"},{"id":"013967a1-ba53-4692-a13a-ceae609481af","data":{"type":"sense","abilityBlockId":19330},"type":"giveAbilityBlock"},{"id":"6849b687-67e5-4e8c-a232-7726c61a63f8","data":{"value":{"value":1},"variable":"ATTRIBUTE_DEX"},"type":"adjValue"},{"id":"6e1941cd-a202-4d1c-a117-e3fc8ac9c1e3","data":{"value":{"value":1},"variable":"ATTRIBUTE_INT"},"type":"adjValue"},{"id":"eabb4cd7-5aad-4f7c-a712-95d5e272bcf3","data":{"title":"Select an Attribute","modeType":"FILTERED","optionType":"ADJ_VALUE","optionsFilters":{"id":"8c1e7659-5029-4d00-8d77-f10f50b4688d","type":"ADJ_VALUE","group":"ATTRIBUTE","value":{"value":1}},"optionsPredefined":[]},"type":"select"},{"id":"13e39aad-cd73-4b63-ae9b-2f8e5b0c12e3","data":{"traitId":2399},"type":"giveTrait"}],"artwork_url":"https://images.demiplane.com/elements/pathfinder-2e/ancestries/ancestry-elf-rm-detail.png?format=webp&quality=90&width=1920","description":"> _Elves are a tall, long-lived people with a strong tradition of art and magic._\n\nAs an ancient people, elves have seen great change and have the perspective that can come only from watching the arc of history. After leaving Golarion in ancient times, they returned to a changed land, and they still struggle to reclaim their ancestral homes. Elves value kindness, intellect, and beauty, with many elves striving to improve their manners, appearance, and culture. Their studies delve into a level of detail that most shorter-lived peoples find excessive or inefficient. Elves are often rather private people, steeped in the secrets of their groves and kinship groups. They're slow to build friendships outside their kinsfolk, as elves who spend their lives among shorter-lived peoples often become morose after watching generations of companions age and die. These elves are known as Forlorn among their fellow elves.\n\nIf you want a character who is [magical](link_trait_1504), mystical, and mysterious, you should play an elf.","content_source_id":1},"after":{"id":3,"name":"Elf","uuid":"1585905187237552","rarity":"COMMON","version":"1.0","trait_id":1348,"meta_data":{"source":{"url":"https://2e.aonprd.com/Ancestries.aspx?ID=60","book":"Player Core","page":"46"}},"created_at":"2023-12-02T22:15:58.556798+00:00","deprecated":null,"operations":[{"id":"2ab7d55b-60a2-4051-9307-e4c73a6d6596","data":{"value":6,"variable":"MAX_HEALTH_ANCESTRY"},"type":"setValue"},{"id":"09cbf36d-44d6-436d-9456-5499516314aa","data":{"value":"medium","variable":"SIZE"},"type":"setValue"},{"id":"72506287-ce22-4033-866d-ab849ac4ec9e","data":{"value":30,"variable":"SPEED"},"type":"setValue"},{"id":"ca332abb-d0ae-43d6-915b-bb85688cf91e","data":{"value":{"valu